function validate([words1, words2]) {
  if (!Array.isArray(words1) || words1.length < 1 || words1.length > 10000) return 'words1 needs 1 to 10^4 words.';
  if (!Array.isArray(words2) || words2.length < 1 || words2.length > 10000) return 'words2 needs 1 to 10^4 words.';
  for (const word of [...words1, ...words2]) {
    if (typeof word !== 'string' || !/^[a-z]{1,10}$/.test(word)) return 'Each word is 1 to 10 lowercase letters.';
  }
  if (new Set(words1).size !== words1.length) return 'The words of words1 must all be different.';
  return null;
}

