function wordSubsets(words1, words2) {
  // Check every pair directly: strike out b's letters one by one from a copy of a.
  const fits = (b, a) => {
    const left = a.split('');
    for (const ch of b) {
      const at = left.indexOf(ch);
      if (at === -1) return false;
      left.splice(at, 1);
    }
    return true;
  };
  return words1.filter(a => words2.every(b => fits(b, a)));
}

