function generate(rand, size) {
  const large = size === 'large';
  const letters = large ? 'abcdefghijklmnopqrstuvwxyz' : 'abcd'.slice(0, 2 + Math.floor(rand() * 3));
  const letter = () => letters[Math.floor(rand() * letters.length)];
  const shuffle = list => { for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; } return list; };
  // Every string of words2 is drawn from one required multiset, so some words1 can satisfy them all.
  const required = Array.from({ length: 1 + Math.floor(rand() * (large ? 6 : 3)) }, letter);
  const count2 = large ? 2000 : 1 + Math.floor(rand() * 3);
  const words2 = [];
  for (let i = 0; i < count2; i++) {
    const part = shuffle(required.slice()).slice(0, 1 + Math.floor(rand() * required.length));
    words2.push(part.join(''));
  }
  const count1 = large ? 2000 : 1 + Math.floor(rand() * 6);
  const maxLength = large ? 10 : 5;
  const seen = new Set();
  for (let tries = 0; seen.size < count1 && tries < 50 * count1; tries++) {
    let chars;
    if (rand() < 0.5 && required.length <= maxLength) {
      chars = rand() < 0.3 ? required.slice(1) : required.slice();
      const length = chars.length + Math.floor(rand() * (maxLength - chars.length + 1));
      while (chars.length < Math.max(1, length)) chars.push(letter());
    } else {
      chars = Array.from({ length: 1 + Math.floor(rand() * maxLength) }, letter);
    }
    seen.add(shuffle(chars).join(''));
  }
  return [[...seen], words2];
}
